  private wantRoll(id: string, tag: any, skill: Skill, dc: number, why: string) { if (this.g.set.askDice && this.s.host.online(id)) { this.s.R.ask({ who: id, kind: 'check', skill, dc, why, adv: 0, tag }); this.s.onDirty() } else { const r = this.s.R.check(id, { skill, dc, why }); this.resolve(id, tag, r) } }
