  private friendIn(text: string, id: string): string | undefined { return this.s.R.heroes().find(q => q !== id && text.includes(this.g.chars[q].name.toLowerCase().split(' ')[0])) ?? id }
  private weaponIn(text: string, id: string): string { const A = this.s.R.attacksOf(id); return (A.find(a => text.includes(a.name.toLowerCase())) ?? (/\b(shoot|bow|arrow|fire at)\b/.test(text) ? A.find(a => a.ranged) : undefined) ?? A[0])?.id ?? '' }
